// Tell TypeScript to allow importing .jsx modules
declare module "*.jsx" {
  const content: any;
  export default content;
}

// Allow importing images and other assets
declare module "*.svg" {
  const content: any;
  export default content;
}

declare module "*.png" {
  const content: any;
  export default content;
}

declare module "*.jpg" {
  const content: any;
  export default content;
}

declare module "*.jpeg" {
  const content: any;
  export default content;
}

declare module "*.gif" {
  const content: any;
  export default content;
}